  const [edit, setEdit] = useState<RecordData | null | undefined>(), [detailId, setDetailId] = useState<string | null>(null), [photos, setPhotos] = useState<File[]>([]), [keptPhotos, setKeptPhotos] = useState<string[]>([]), [error, setError] = useState(''), [busy, setBusy] = useState(false), [exportBusy, setExportBusy] = useState(false), [exportError, setExportError] = useState('');
  const tabId = useId();
