      {view==='individual'&&(filtered.length?<div className="room-grid">{filtered.map(room => { const overview = summaries.find(row => row.roomId === room.id), tenant = data.tenants.find(row => row.roomId === room.id && row.status === 'active'), property = data.properties.find(row => row.id === room.propertyId), image = imageIds(room)[0]; return <article className="room-card" key={room.id}><div className={`room-visual room-visual-${room.status}`}>{image ? <img src={fileUrl(image)} alt={`Phòng ${room.code}`} style={{ width: '100%', height: '100%', objectFit: 'cover', position: 'absolute', inset: 0 }}/> : <><Home size={50} strokeWidth={1}/><span className="room-visual-code">{room.code}</span></>}<Badge value={room.status}/><div className="room-floor">Tầng {room.floor || 0}</div></div><div className="room-card-body"><div className="room-card-title"><div><h3>Phòng {room.code}</h3><span>{property?.name}</span></div><span className="room-size">{room.area} m²</span></div><p className="room-price">{money(overview?.contractRent??room.price)}<span>/ tháng · {overview?.contractRent!=null?'Theo hợp đồng':'Giá niêm yết'}</span></p><div className="room-details"><span><Users size={14}/>{room.capacity} người</span><span>{room.amenities || 'Chưa có tiện nghi'}</span></div><div className="room-tenant"><span className={`tiny-avatar ${tenant ? '' : 'avatar-empty'}`}>{tenant ? tenant.name.charAt(0) : <Users size={14}/>}</span><span>{tenant?.name || (room.status === 'vacant' ? 'Sẵn sàng đón người thuê mới' : 'Chưa có người thuê')}</span></div><div className="room-card-footer"><button className="btn btn-sm" onClick={() => setDetailId(room.id)}>Thông tin phòng<ArrowUpRight size={14}/></button>{landlord && <button className="icon-button" aria-label={`Chỉnh sửa phòng ${room.code}`} onClick={() => openEdit(room)}><FileText size={17}/></button>}</div></div></article>; })}</div>:<section className="card"><EmptyState title="Chưa có phòng phù hợp" description="Thử bộ lọc khác hoặc thêm phòng mới."/></section>)}
